impl Lower for crate::ExprCompare {
    fn lower(&self, builder: &mut Builder) -> BuildId<Self> {
        let ops = builder.collect::<crate::CmpOp, _>(self.ops.iter(), |_, item| item.encode());
        let operands = builder
            .collect::<Handle<crate::Expr>, _>(self.operands.iter(), |builder, item| {
                u64::from(crate::Expr::lower(item, builder).slot)
            });
        builder.push_expr_compare(self.range(), [ops, operands])
    }
}
impl Builder {
    #[inline]
    fn push_expr_compare(
        &mut self,
        range: ruff_text_size::TextRange,
        [ops, operands]: [u64; 2],
    ) -> BuildId<crate::ExprCompare> {
        let mut row = Row::new(NodeKind::ExprCompare, range);
        let [start, len] = split_words(ops);
        if len == 1 && split_words(operands)[1] == 2 {
            row.set_expr_compare_single_op(self.ast.extra[start as usize].to_le_bytes()[0] + 1);
        }
        let [ops, operands] =
            super::list::Interval::pack_pair(&mut self.ast.extra, [ops, operands]);
        row.set_expr_compare_ops(split_words(ops)[0]);
        row.set_expr_compare_operands(operands);
        self.push(row)
    }
}
impl Rebuild for crate::ExprCompare {
    fn rebuild(view: View<'_, Self>) -> Self {
        Self {
            node_index: view.node_index(),
            range: view.range(),
            ops: view.ops().iter().collect(),
            operands: view.operands().iter().map(View::to_owned_node).collect(),
        }
    }
}
impl<'a> View<'a, crate::ExprCompare> {
    /// Returns the operands and operator of a single comparison.
    #[inline]
    pub fn as_single(self) -> Option<(View<'a, crate::Expr>, crate::CmpOp, View<'a, crate::Expr>)> {
        let operator = self.row.expr_compare_single_op().checked_sub(1)?;
        let start = split_words(self.row.expr_compare_operands())[0] as usize;
        let &[left, right] = self.ast.extra.get(start..)?.first_chunk()?;
        Some((
            self.ast.child(u64::from(left)),
            crate::CmpOp::decode(u64::from(operator)),
            self.ast.child(u64::from(right)),
        ))
    }

    #[inline]
    pub fn ops(self) -> List<'a, crate::CmpOp> {
        let word = super::list::Interval::preceding(
            self.row.expr_compare_operands(),
            u64::from(self.row.expr_compare_ops()),
        );
        List::new(self.ast, word)
    }
    #[inline]
    pub fn operands(self) -> NodeList<'a, crate::Expr> {
        let word = self.row.expr_compare_operands();
        List::new(self.ast, word)
    }
}
